const input = $input.first().json;
const config = {
  dataset: input.dataset || "data/usd-layer1-backtester/run-v1.json",
  model: input.model || "challenger",
  from: input.from || "2024-01-02",
  to: input.to || "2024-01-31",
  validation: input.validation || "structural",
  markets: Array.isArray(input.markets) && input.markets.length ? input.markets.slice() : null
};
if (!/^\d{4}-\d{2}-\d{2}$/.test(config.from) || !/^\d{4}-\d{2}-\d{2}$/.test(config.to)) {
  throw new Error("from and to must be YYYY-MM-DD");
}
if (config.from > config.to) {
  throw new Error("from must not be after to");
}
return [{ json: config }];

const listed = JSON.parse($input.first().json.stdout);
const config = $("Run configuration").first().json;
if (!Array.isArray(listed.dates)) {
  throw new Error("the date list did not return a dates array");
}
if (listed.dates.length === 0) {
  throw new Error("no USD sessions exist in the requested window");
}
return listed.dates.map((date) => ({
  json: {
    date,
    model: config.model,
    dataset: config.dataset,
    validation: config.validation
  }
}));

const decisions = $input.all()
  .map((item) => item.json)
  .filter((decision) => decision && decision.date);
const __declared = $("Run configuration").first().json.markets;
const MARKETS = Array.isArray(__declared) && __declared.length
  ? __declared.slice()
  : Array.from(new Set(decisions.flatMap((decision) => (decision.tests && decision.tests.scored_markets) || Object.keys(decision.results || {})))).sort();
const round = (value, decimals = 4) => {
  const factor = Math.pow(10, decimals);
  const rounded = Math.round(value * factor) / factor;
  return Object.is(rounded, -0) ? 0 : rounded;
};
const wilsonLowerBound = (hits, scored, z = 1.96) => {
  if (scored === 0) return null;
  const p = hits / scored;
  const denominator = 1 + (z * z) / scored;
  const centre = p + (z * z) / (2 * scored);
  const margin = z * Math.sqrt((p * (1 - p)) / scored + (z * z) / (4 * scored * scored));
  return round((centre - margin) / denominator, 4);
};
const emptyTally = () => ({ hit: 0, miss: 0, flat: 0, no_outcome: 0, no_call: 0, scored: 0, accuracy: null, wilson_lower_95: null });
const addResult = (tally, result) => {
  if (Object.prototype.hasOwnProperty.call(tally, result)) tally[result] += 1;
  else tally.no_outcome += 1;
};
const finishTally = (tally) => {
  tally.scored = tally.hit + tally.miss;
  tally.accuracy = tally.scored > 0 ? round(tally.hit / tally.scored, 4) : null;
  tally.wilson_lower_95 = wilsonLowerBound(tally.hit, tally.scored);
  return tally;
};
const statuses = { blocked: 0, allowed: 0, abstained: 0 };
const validation = { structural_accepted: 0, structural_blocked: 0, receipted_complete: 0, receipted_incomplete: 0 };
const markets = {};
for (const market of MARKETS) markets[market] = emptyTally();
const pooled = emptyTally();
const blocked_reasons = {};
for (const decision of decisions) {
  if (Object.prototype.hasOwnProperty.call(statuses, decision.status)) statuses[decision.status] += 1;
  const structural = decision.validation
    ? (decision.validation.structural_accepted === undefined ? decision.validation.accepted : decision.validation.structural_accepted)
    : false;
  if (structural) validation.structural_accepted += 1;
  else validation.structural_blocked += 1;
  if (decision.validation && decision.validation.receipted && decision.validation.receipted.complete) validation.receipted_complete += 1;
  else validation.receipted_incomplete += 1;
  for (const reason of (decision.validation && decision.validation.reasons) || []) {
    blocked_reasons[reason.code] = (blocked_reasons[reason.code] || 0) + 1;
  }
  if (!decision.results) continue;
  for (const market of MARKETS) {
    const result = decision.results[market] || "no_outcome";
    addResult(markets[market], result);
    addResult(pooled, result);
  }
}
for (const market of MARKETS) finishTally(markets[market]);
finishTally(pooled);
const dates = decisions.map((decision) => decision.date).filter(Boolean).sort();
const config = $("Run configuration").first().json;
return [{
  json: {
    controller_version: "usd-l1-backtest-controller-v1",
    source: "n8n:usd-l1-backtest-controller",
    dataset: { path: config.dataset },
    validation_mode: config.validation,
    layer1: { id: config.model },
    window: {
      from: dates.length ? dates[0] : null,
      to: dates.length ? dates[dates.length - 1] : null,
      requested_dates: decisions.length
    },
    summary: {
      sessions: decisions.length,
      statuses,
      validation,
      blocked_reasons,
      markets,
      pooled,
      participation: round(statuses.allowed / Math.max(1, statuses.allowed + statuses.abstained), 4)
    },
    decisions: decisions
  }
}];
